	}
	project := store.Project{Name: "shop", HerdrWorkspaceID: "w1", LeadPaneID: "w1:p1", LeadLabel: "posse:shop:lead"}
	task := store.Task{Seq: 1, WorktreePath: sandbox, HerdrWorkspaceID: "w1", PaneID: "w1:p3", PaneLabel: "posse:shop:t1"}
