		for _, pane := range snapshot.Panes {
			if pane.PaneID == paneID {
				cwd = pane.CWD
				if pane.Agent != "" {
					name = pane.Agent
				}
				break
			}
		}
		for _, agent := range snapshot.Agents {
			if agent.PaneID == paneID && agent.Agent != "" {
				name = agent.Agent
				break
			}
		}
