		result, err := json.Marshal(map[string]any{"process_info": map[string]any{"pane_id": paneID, "shell_pid": pid, "foreground_process_group_id": pid, "foreground_processes": []map[string]any{{"pid": pid, "name": name, "cwd": cwd}}}})
